import{_ as i,b as o,c as r,g as l}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"时间上的概率推理","description":"","frontmatter":{"title":"时间上的概率推理","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/14.md","filePath":"articles/ai/books/ai-modern-approach/14.md"}'),s={name:"articles/ai/books/ai-modern-approach/14.md"};function n(a,t,e,g,d,_){return o(),r("div",null,[...t[0]||(t[0]=[l('<p>第 14 章在第 13 章概率论基础上，引入贝叶斯网络作为表示不确定性和进行推理的核心工具。重点包括：</p><h2 id="贝叶斯网络表示" tabindex="-1">贝叶斯网络表示</h2><ul><li><strong>节点</strong> = 随机变量，<strong>有向边</strong> = 直接因果/概率依赖</li><li><strong>条件概率表（CPT）</strong>：每个节点给定父节点取值的条件概率</li><li><strong>联合分布的分解</strong>：P(X₁, …, Xₙ) = ∏ᵢ P(Xᵢ | Parents(Xᵢ))</li></ul><h2 id="贝叶斯网络语义" tabindex="-1">贝叶斯网络语义</h2><ul><li><strong>条件独立性</strong>：给定父节点，每个节点与所有非后代节点条件独立（马尔可夫毯）</li><li><strong>d-分离</strong>：用于判断网络中两变量是否给定某些变量条件独立</li></ul><h2 id="精确推理" tabindex="-1">精确推理</h2><ul><li><strong>枚举法</strong>：使用联合分布全概率求和，指数复杂度</li><li><strong>变量消元（Variable Elimination）</strong>：通过因子动态规划，避免重复计算</li><li>消元顺序影响计算复杂度（需寻找最优顺序，NP 难）</li></ul><h2 id="近似推理" tabindex="-1">近似推理</h2><ul><li><strong>直接采样</strong>：从网络生成样本，计算后验近似</li><li><strong>拒绝采样</strong>：仅保留与证据一致的样本，但效率低</li><li><strong>似然加权</strong>：固定证据，仅采样非证据变量，用权值修正</li><li><strong>吉布斯采样</strong>：马尔可夫链蒙特卡洛（MCMC）方法，逐个变量采样</li></ul><h2 id="贝叶斯网络的应用" tabindex="-1">贝叶斯网络的应用</h2><ul><li>诊断、预测、决策支持系统</li><li>学习 CPT（参数学习）和网络结构（结构学习）</li></ul>',11)])])}const u=i(s,[["render",n]]);export{p as __pageData,u as default};
